import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public final class Processor {
    public record Result(String key, int payload, long processedAt) {}
    public record Effect(String key, int payload) {}

    private final long window;
    public final List<Effect> effects = new ArrayList<>();
    private final Map<String, Result> seen = new HashMap<>();

    public Processor(long window) {
        this.window = window;
    }

    public Result process(String key, int payload, long now) {
        Result cached = seen.get(key);
        if (cached != null) {
            return cached;
        }
        effects.add(new Effect(key, payload));
        Result result = new Result(key, payload, now);
        seen.put(key, result);
        return result;
    }
}

