public final class ProcessorTest {
    public static void main(String[] args) {
        checkDuplicateKeyWithinWindowNotReexecuted();
        checkDifferentKeysBothExecute();
        checkReexecutesAfterWindowExpires();
        System.out.println("all tests passed");
    }

    static void checkDuplicateKeyWithinWindowNotReexecuted() {
        Processor p = new Processor(10);
        Processor.Result first = p.process("order-1", 5, 0);
        Processor.Result second = p.process("order-1", 999, 5);
        if (!second.equals(first)) throw new AssertionError("expected same result");
        if (p.effects.size() != 1) throw new AssertionError("expected 1 effect, got " + p.effects.size());
    }

    static void checkDifferentKeysBothExecute() {
        Processor p = new Processor(10);
        p.process("a", 1, 0);
        p.process("b", 2, 0);
        if (p.effects.size() != 2) throw new AssertionError("expected 2 effects, got " + p.effects.size());
    }

    static void checkReexecutesAfterWindowExpires() {
        Processor p = new Processor(10);
        p.process("order-1", 5, 0);
        p.process("order-1", 5, 9);
        if (p.effects.size() != 1) throw new AssertionError("expected 1 effect before expiry");
        p.process("order-1", 7, 10);
        if (p.effects.size() != 2) throw new AssertionError("expected 2 effects after expiry");
        if (p.effects.get(1).payload() != 7) throw new AssertionError("expected fresh payload 7");
    }
}

